        onPointerMissed={() => {
          if (!useOrb.getState().playing)
            useOrb.getState().set({ selected: undefined });
        }}
      >
        <AdaptiveResolution onChange={setRenderDpr} />
        <Scene onReady={onReady} />
      </Canvas>
    </Boundary>
  );
}

