import type { ModelCommand } from "./protocol";

export const localModelingInstructions = `When localModeling is true, use kind generated with a typed local Blender job for genuinely new shapes that benefit from custom meshes, extrusions, lathes or modifiers. Mix useful catalog, procedural and generated geometry; new-only still forbids catalog reuse. Reserve the entity first without geometry, optionally provide a procedural coarse preview, then send one refined generated job. Do not repeat the same Blender job for coarse and refined stages. Never supply the model metadata field: the trusted local executor creates it. Jobs use Y-up coordinates, radians for XYZ rotation, positive scale, and hex colors. Extrude profile points [x,y] along Z using depth; lathe profile points [radius,height] around Y. Primitive box/sphere/cylinder/cone have size/diameter 2 before scaling. Set collision platform only for a generated walkable platform; otherwise use none. Use bounded, low-complexity jobs. No Python, URLs or files. Preserve stable entity IDs on edits. Use set_material for a recolor without rebuilding the mesh.`;

export const browserModelingInstructions = `When browserModeling is true, use kind generated with a browser-manifold recipe shaped as {backend:"browser-manifold",recipe:{version:1,revision,output,nodes}} for genuinely new shapes. Prefer structured browser-manifold recipes; for an unusual shape that needs deterministic procedural construction, you may instead use {backend:"browser-procedural",source:{version:1,language:"quickjs",seed,code}} where code is a bounded expression returning one complete versioned recipe. The browser builder supports only centered box(size), sphere(radius, segments), cylinder(radius, depth, axis x/y/z), revolve(profile, segments), extrude(profile, depth), bounded closed triangle mesh(vertices, triangles), capped open tube(path, radius, segments), transform(input, position, rotation, scale), mirror(input, normal), linear-array(input, count, offset), instances(input, transforms), compose(inputs), and boolean union/subtract/intersect nodes. Mesh nodes use 4–4096 finite Y-up vertices within ±100 meters and 4–8192 triangles; they must form one connected, positively oriented closed shell with no duplicate, unused, degenerate, overlapping, or self-intersecting triangles. Mesh validation is bounded and fail-closed; use separate graph nodes for compound solids. Tube paths use 2–63 unique Float32-normalized Y-up points within ±100 meters, radius greater than 1e-4 and at most 50 meters, and 3–64 radial segments (default 16). Tubes are open polylines with flat caps; reject closed loops, repeated endpoints, variable radius, twist, and custom profiles. Reject ambiguous reversals, degenerate segments, self-overlap, and generated vertices outside ±100 meters. Mirror normals must be nonzero and define a plane through the origin. Compose, linear-array, and instances only combine separated solids: touching or overlapping copies are rejected; use boolean union when surfaces should merge. Linear arrays use 2–32 copies with a nonzero per-copy offset. Instances use 1–32 explicit positive-scale XYZ transforms. These operations bake copies into one geometry output; they do not provide scene parenting, separate entity IDs, or GPU instancing. Revolve profiles use [radius,height] points with nonnegative radius and a full 360-degree sweep around Y, preserving the explicit heights without automatic centering; segments default to 32 (maximum 64). Extrude profiles use [x,y] points along Z, centered from -depth/2 to +depth/2. Both profiles are simple closed polygons with 3–64 distinct points and implicit closing edges; do not repeat the first point, request holes, or request a partial sweep. Keep recipes within 64 nodes, depth 16, 64 expanded geometry leaves, segments 64, and the evaluator's 100,000-triangle and 8 MiB intermediate mesh limits; the baked GLB must stay within 2 MiB. Dimensions and positions are meters in a Y-up world; rotations are radians using XYZ order; scale is positive. Reserve the entity first without geometry, then send one refined browser job; do not send a coarse browser job. Never supply model metadata: the trusted browser builder creates it. Every node ID must be unique. recipe.output must exactly match an existing node ID; every node must be reachable from that output. Node IDs are separate from the scene entity ID. For one-node extrusion, use output:"mesh" and nodes:[{id:"mesh",kind:"extrude",profile:[[-1,-1],[1,-1],[0,1]],depth:1}]. Preserve editable recipe revisions and stable node/entity IDs on edits. Follow new-only rules. Do not pair this backend with Blender, and do not claim support for partial sweeps, external scripts, URLs, or external assets.`;

export function modelingInstructions(
  localModeling = false,
  browserModeling = false,
) {
  return [
    localModeling ? localModelingInstructions : "",
    browserModeling ? browserModelingInstructions : "",
  ]
    .filter(Boolean)
    .join(" ");
}

/** Model output may request construction, but cannot assert trusted artifact identity. */
export function assertModelingCommand(
  command: ModelCommand,
  available: boolean,
  browserAvailable = false,
) {
  if (
    command.type === "reserve_entity" &&
    command.entity.geometry?.kind === "generated"
  )
    throw Error(
      "Reserve the object first, then request its local model with set_geometry.",
    );
  if (command.type !== "set_geometry" || command.geometry.kind !== "generated")
    return;
  const browserBackend =
    "backend" in command.geometry.job &&
    (command.geometry.job.backend === "browser-manifold" ||
      command.geometry.job.backend === "browser-procedural");
  if (browserBackend) {
    if (!browserAvailable)
      throw Error(
        "Browser modeling is unavailable. Use a browser with Web Workers and WebAssembly support.",
      );
    if ("model" in command.geometry && command.geometry.model)
      throw Error(
        "Generated model identities must come from the browser builder.",
      );
    if (command.geometry.detail !== "refined")
      throw Error(
        "Browser modeling jobs must provide refined geometry; use a procedural preview first.",
      );
    return;
  }
  if (!available)
    throw Error(
      "This modeling job is unsupported. Request a browser-manifold recipe instead.",
    );
  if ("model" in command.geometry && command.geometry.model)
    throw Error("Generated model identities must come from the local builder.");
  if (command.geometry.detail !== "refined")
    throw Error(
      "Local Blender jobs must provide refined geometry; use a procedural preview first.",
    );
}

src/lib/browser-modeling.ts:
import { z } from "zod";
import {
  MAX_BROWSER_MESH_RECIPE_TRIANGLES,
  MAX_BROWSER_MESH_RECIPE_VERTICES,
  MAX_BROWSER_MESH_TRIANGLES,
  MAX_BROWSER_MESH_VERTICES,
} from "./browser-mesh-validation";
import {
  DEFAULT_BROWSER_TUBE_SEGMENTS,
  MAX_BROWSER_TUBE_PATH_POINTS,
  MAX_BROWSER_TUBE_RADIUS,
  MAX_BROWSER_TUBE_SEGMENTS,
  MIN_BROWSER_TUBE_RADIUS,
  browserTubeMeshCounts,
} from "./browser-tube-validation";

const MAX_NODES = 64;
const MAX_DEPTH = 16;
const MAX_SEGMENTS = 64;
const MAX_COORDINATE_METERS = 100;
const MAX_DIMENSION_METERS = 100;
const MAX_ROTATION_RADIANS = 100;
const MAX_SCALE = 20;
const MAX_COMPOSE_INPUTS = 32;
const MAX_COPY_COUNT = 32;
const MAX_EXPANDED_LEAVES = 64;

const identifier = z.string().regex(/^[a-zA-Z0-9_-]{1,64}$/);
const coordinate = z
  .number()
  .finite()
  .min(-MAX_COORDINATE_METERS)
  .max(MAX_COORDINATE_METERS);
const rotation = z
  .number()
  .finite()
  .min(-MAX_ROTATION_RADIANS)
  .max(MAX_ROTATION_RADIANS);
const dimension = z.number().finite().gt(0).max(MAX_DIMENSION_METERS);
const positiveScale = z.number().finite().gt(0).max(MAX_SCALE);
const vector3 = z.tuple([coordinate, coordinate, coordinate]);
const size3 = z.tuple([dimension, dimension, dimension]);
const scale3 = z.tuple([positiveScale, positiveScale, positiveScale]);
const segments = z.number().int().min(3).max(MAX_SEGMENTS);

const boxNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("box"),
    size: size3,
  })
  .strict();

const sphereNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("sphere"),
    radius: dimension,
    segments: segments.default(32),
  })
  .strict();

const cylinderNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("cylinder"),
    radius: dimension,
    depth: dimension,
    axis: z.enum(["x", "y", "z"]),
    segments: segments.default(32),
  })
  .strict();

const extrudeNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("extrude"),
    profile: z
      .array(z.tuple([coordinate, coordinate]))
      .min(3)
      .max(64),
    depth: dimension,
  })
  .strict();

const revolveRadius = z
  .number()
  .finite()
  .max(MAX_COORDINATE_METERS)
  .refine((value) => value >= 0, {
    message: "Revolve profile radius must be nonnegative.",
  });

const revolveNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("revolve"),
    profile: z
      .array(z.tuple([revolveRadius, coordinate]))
      .min(3)
      .max(64),
    segments: segments.default(32),
  })
  .strict();

const meshIndex = z
  .number()
  .int()
  .nonnegative()
  .max(MAX_BROWSER_MESH_VERTICES - 1);
const meshNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("mesh"),
    vertices: z.array(vector3).min(4).max(MAX_BROWSER_MESH_VERTICES),
    triangles: z
      .array(z.tuple([meshIndex, meshIndex, meshIndex]))
      .min(4)
      .max(MAX_BROWSER_MESH_TRIANGLES),
  })
  .strict();

const tubeNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("tube"),
    path: z.array(vector3).min(2).max(MAX_BROWSER_TUBE_PATH_POINTS),
    radius: z
      .number()
      .finite()
      .gt(MIN_BROWSER_TUBE_RADIUS)
      .max(MAX_BROWSER_TUBE_RADIUS),
    segments: z
      .number()
      .int()
      .min(3)
      .max(MAX_BROWSER_TUBE_SEGMENTS)
      .default(DEFAULT_BROWSER_TUBE_SEGMENTS),
  })
  .strict();

const composeNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("compose"),
    inputs: z.array(identifier).min(2).max(MAX_COMPOSE_INPUTS),
  })
  .strict();

const mirrorNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("mirror"),
    input: identifier,
    normal: vector3.refine(
      ([x, y, z]) => x * x + y * y + z * z > 1e-12,
      "Mirror normal must be nonzero.",
    ),
  })
  .strict();

const linearArrayNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("linear-array"),
    input: identifier,
    count: z.number().int().min(2).max(MAX_COPY_COUNT),
    offset: vector3.refine(
      ([x, y, z]) => x * x + y * y + z * z > 1e-12,
      "Linear array offset must be nonzero.",
    ),
  })
  .strict();

const instanceTransformSchema = z
  .object({
    position: vector3,
    rotation: z.tuple([rotation, rotation, rotation]),
    scale: scale3,
  })
  .strict();

const instancesNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("instances"),
    input: identifier,
    transforms: z.array(instanceTransformSchema).min(1).max(MAX_COPY_COUNT),
  })
  .strict();

const transformNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("transform"),
    input: identifier,
    position: vector3,
    rotation: z.tuple([rotation, rotation, rotation]),
    scale: scale3,
  })
  .strict();

const booleanNodeSchema = z
  .object({
    id: identifier,
    kind: z.literal("boolean"),
    operation: z.enum(["union", "subtract", "intersect"]),
    operands: z.array(identifier).min(2).max(MAX_NODES),
  })
  .strict();

/** A centered primitive or a data-only graph operation in the browser recipe. */
export const browserModelNodeSchema = z.discriminatedUnion("kind", [
  boxNodeSchema,
  sphereNodeSchema,
  cylinderNodeSchema,
  extrudeNodeSchema,
  revolveNodeSchema,
  meshNodeSchema,
  tubeNodeSchema,
  composeNodeSchema,
  mirrorNodeSchema,
  linearArrayNodeSchema,
  instancesNodeSchema,
  transformNodeSchema,
  booleanNodeSchema,
]);

const browserModelRecipeBaseSchema = z
  .object({
    version: z.literal(1),
    revision: z.number().int().min(0).max(2_147_483_647),
    output: identifier,
    nodes: z.array(browserModelNodeSchema).min(1).max(MAX_NODES),
  })
  .strict();

export type BrowserModelNode = z.infer<typeof browserModelNodeSchema>;
export type BrowserModelRecipe = z.infer<typeof browserModelRecipeBaseSchema>;

function graphIssue(message: string, path: (string | number)[] = []) {
  return { code: "custom" as const, message, path };
}

type PolygonProfile = readonly (readonly [number, number])[];

function cross(ax: number, ay: number, bx: number, by: number): number {
  return ax * by - ay * bx;
}

function orientation(
  a: readonly [number, number],
  b: readonly [number, number],
  c: readonly [number, number],
): number {
  return cross(b[0] - a[0], b[1] - a[1], c[0] - a[0], c[1] - a[1]);
}

function onSegment(
  a: readonly [number, number],
  b: readonly [number, number],
  point: readonly [number, number],
): boolean {
  const epsilon = 1e-10;
  return (
    point[0] >= Math.min(a[0], b[0]) - epsilon &&
    point[0] <= Math.max(a[0], b[0]) + epsilon &&
    point[1] >= Math.min(a[1], b[1]) - epsilon &&
    point[1] <= Math.max(a[1], b[1]) + epsilon
  );
}

function segmentsIntersect(
  a: readonly [number, number],
  b: readonly [number, number],
  c: readonly [number, number],
  d: readonly [number, number],
): boolean {
  const epsilon = 1e-10;
  const abC = orientation(a, b, c);
  const abD = orientation(a, b, d);
  const cdA = orientation(c, d, a);
  const cdB = orientation(c, d, b);
  if (
    Math.abs(abC) <= epsilon &&
    Math.abs(abD) <= epsilon &&
    Math.abs(cdA) <= epsilon &&
    Math.abs(cdB) <= epsilon
  )
    return (
      onSegment(a, b, c) ||
      onSegment(a, b, d) ||
      onSegment(c, d, a) ||
      onSegment(c, d, b)
    );
  return (
    ((abC > epsilon && abD < -epsilon) ||
      (abC < -epsilon && abD > epsilon) ||
      (Math.abs(abC) <= epsilon && onSegment(a, b, c)) ||
      (Math.abs(abD) <= epsilon && onSegment(a, b, d))) &&
    ((cdA > epsilon && cdB < -epsilon) ||
      (cdA < -epsilon && cdB > epsilon) ||
      (Math.abs(cdA) <= epsilon && onSegment(c, d, a)) ||
      (Math.abs(cdB) <= epsilon && onSegment(c, d, b)))
  );
}

function polygonProfileIssue(
  profile: PolygonProfile,
  profileName: string,
): string | undefined {
  const epsilon = 1e-10;
  const points = profile;
  for (let first = 0; first < points.length; first += 1) {
    for (let second = first + 1; second < points.length; second += 1) {
      if (
        points[first][0] === points[second][0] &&
        points[first][1] === points[second][1]
      )
        return `${profileName} vertices must be distinct.`;
    }
  }

  let twiceArea = 0;
  for (let index = 0; index < points.length; index += 1) {
    const next = points[(index + 1) % points.length];
    twiceArea += points[index][0] * next[1] - next[0] * points[index][1];
    const edgeX = next[0] - points[index][0];
    const edgeY = next[1] - points[index][1];
    if (edgeX * edgeX + edgeY * edgeY <= epsilon)
      return `${profileName} edges must have nonzero length.`;

    const previous = points[(index + points.length - 1) % points.length];
    const previousX = points[index][0] - previous[0];
    const previousY = points[index][1] - previous[1];
    if (
      Math.abs(cross(previousX, previousY, edgeX, edgeY)) <= epsilon &&
      previousX * edgeX + previousY * edgeY < -epsilon
    )
      return `${profileName} must not backtrack along an edge.`;
  }
  if (Math.abs(twiceArea) <= epsilon)
    return `${profileName} must enclose a nonzero area.`;

  for (let first = 0; first < points.length; first += 1) {
    const firstEnd = (first + 1) % points.length;
    for (let second = first + 1; second < points.length; second += 1) {
      const secondEnd = (second + 1) % points.length;
      const adjacent =
        first === second || firstEnd === second || secondEnd === first;
      if (
        !adjacent &&
        segmentsIntersect(
          points[first],
          points[firstEnd],
          points[second],
          points[secondEnd],
        )
      )
        return `${profileName} edges must not intersect.`;
    }
  }
  return undefined;
}

/**
 * A browser recipe is a directed acyclic graph. Primitive dimensions are
 * meters, positions are Y-up meters, and rotations are radians.
 */
export const browserModelRecipeSchema =
  browserModelRecipeBaseSchema.superRefine((recipe, context) => {
    const byId = new Map<string, BrowserModelNode>();
    recipe.nodes.forEach((node, index) => {
      if (byId.has(node.id)) {
        context.addIssue(
          graphIssue(`Duplicate browser recipe node ID: ${node.id}.`, [
            "nodes",
            index,
            "id",
          ]),
        );
      } else byId.set(node.id, node);
    });

    if (!byId.has(recipe.output))
      context.addIssue(
        graphIssue(
          `Browser recipe output node does not exist: ${recipe.output}.`,
          ["output"],
        ),
      );

    const references = (node: BrowserModelNode): string[] => {
      if (
        node.kind === "transform" ||
        node.kind === "mirror" ||
        node.kind === "linear-array" ||
        node.kind === "instances"
      )
        return [node.input];
      if (node.kind === "boolean") return node.operands;
      if (node.kind === "compose") return node.inputs;
      return [];
    };

    recipe.nodes.forEach((node, index) => {
      if (node.kind === "mesh") {
        const meshVertices = new Set<number>();
        node.triangles.forEach((triangle, triangleIndex) => {
          const [a, b, c] = triangle;
          if (
            a >= node.vertices.length ||
            b >= node.vertices.length ||
            c >= node.vertices.length
          )
            context.addIssue(
              graphIssue("Browser mesh triangle index is out of range.", [
                "nodes",
                index,
                "triangles",
                triangleIndex,
              ]),
            );
          if (a === b || b === c || c === a)
            context.addIssue(
              graphIssue("Browser mesh triangles must use distinct vertices.", [
                "nodes",
                index,
                "triangles",
                triangleIndex,
              ]),
            );
          meshVertices.add(a);
          meshVertices.add(b);
          meshVertices.add(c);
        });
        if (meshVertices.size !== node.vertices.length)
          context.addIssue(
            graphIssue("Browser mesh vertices must all be referenced.", [
              "nodes",
              index,
              "vertices",
            ]),
          );
      }
      if (node.kind === "extrude" || node.kind === "revolve") {
        const issue = polygonProfileIssue(
          node.profile,
          node.kind === "extrude" ? "Extrude profile" : "Revolve profile",
        );
        if (issue)
          context.addIssue(graphIssue(issue, ["nodes", index, "profile"]));
      }
      const refs = references(node);
      const seenRefs = new Set<string>();
      refs.forEach((reference, refIndex) => {
        if (seenRefs.has(reference))
          context.addIssue(
            graphIssue(`Browser recipe node repeats operand: ${reference}.`, [
              "nodes",
              index,
              node.kind === "boolean" || node.kind === "compose"
                ? node.kind === "boolean"
                  ? "operands"
                  : "inputs"
                : "input",
              ...(node.kind === "boolean" || node.kind === "compose"
                ? [refIndex]
                : []),
            ]),
          );
        seenRefs.add(reference);
        if (!byId.has(reference))
          context.addIssue(
            graphIssue(
              `Browser recipe reference does not exist: ${reference}.`,
              [
                "nodes",
                index,
                node.kind === "transform" ? "input" : "operands",
                ...(node.kind === "boolean" ? [refIndex] : []),
              ],
            ),
          );
      });
    });

    const meshVertices = recipe.nodes.reduce((total, node) => {
      if (node.kind === "mesh") return total + node.vertices.length;
      if (node.kind === "tube")
        return (
          total +
          browserTubeMeshCounts(node.path.length, node.segments).vertices
        );
      return total;
    }, 0);
    const meshTriangles = recipe.nodes.reduce((total, node) => {
      if (node.kind === "mesh") return total + node.triangles.length;
      if (node.kind === "tube")
        return (
          total +
          browserTubeMeshCounts(node.path.length, node.segments).triangles
        );
      return total;
    }, 0);
    if (meshVertices > MAX_BROWSER_MESH_RECIPE_VERTICES)
      context.addIssue(
        graphIssue(
          `Browser recipe mesh vertices exceed ${MAX_BROWSER_MESH_RECIPE_VERTICES}.`,
          ["nodes"],
        ),
      );
    if (meshTriangles > MAX_BROWSER_MESH_RECIPE_TRIANGLES)
      context.addIssue(
        graphIssue(
          `Browser recipe mesh triangles exceed ${MAX_BROWSER_MESH_RECIPE_TRIANGLES}.`,
          ["nodes"],
        ),
      );

    const state = new Map<string, "visiting" | "visited">();
    const reachable = new Set<string>();
    let hasCycle = false;
    const visit = (id: string, path: string[]) => {
      const currentState = state.get(id);
      if (currentState === "visiting") {
        hasCycle = true;
        context.addIssue(
          graphIssue(
            `Browser recipe graph contains a cycle: ${[...path, id].join(" -> ")}.`,
            ["output"],
          ),
        );
        return;
      }
      if (currentState === "visited") return;
      const node = byId.get(id);
      if (!node) return;
      state.set(id, "visiting");
      reachable.add(id);
      const refs = references(node);
      refs.forEach((reference) => visit(reference, [...path, id]));
      state.set(id, "visited");
    };

    if (byId.has(recipe.output)) visit(recipe.output, []);

    if (!hasCycle && byId.has(recipe.output)) {
      const heights = new Map<string, number>();
      const heightOf = (id: string): number => {
        const cached = heights.get(id);
        if (cached !== undefined) return cached;
        const node = byId.get(id);
        if (!node) return 0;
        const refs = references(node);
        const height =
          refs.length === 0
            ? 1
            : 1 + Math.max(...refs.map((reference) => heightOf(reference)));
        heights.set(id, height);
        return height;
      };
      const depth = heightOf(recipe.output);
      if (depth > MAX_DEPTH)
        context.addIssue(
          graphIssue(
            `Browser recipe graph depth exceeds ${MAX_DEPTH} nodes (found ${depth}).`,
            ["output"],
          ),
        );

      const expandedLeaves = new Map<string, number>();
      const expandedLeavesOf = (id: string): number => {
        const cached = expandedLeaves.get(id);
        if (cached !== undefined) return cached;
        const node = byId.get(id);
        if (!node) return 0;
        let count: number;
        if (node.kind === "compose")
          count = node.inputs.reduce(
            (total, reference) => total + expandedLeavesOf(reference),
            0,
          );
        else if (node.kind === "boolean")
          count = node.operands.reduce(
            (total, reference) => total + expandedLeavesOf(reference),
            0,
          );
        else if (node.kind === "linear-array")
          count = node.count * expandedLeavesOf(node.input);
        else if (node.kind === "instances")
          count = node.transforms.length * expandedLeavesOf(node.input);
        else if (node.kind === "transform" || node.kind === "mirror")
          count = expandedLeavesOf(node.input);
        else count = 1;
        expandedLeaves.set(id, count);
        return count;
      };
      const outputLeaves = expandedLeavesOf(recipe.output);
      if (outputLeaves > MAX_EXPANDED_LEAVES)
        context.addIssue(
          graphIssue(
            `Browser recipe expands beyond ${MAX_EXPANDED_LEAVES} geometry leaves.`,
            ["output"],
          ),
        );
    }

    recipe.nodes.forEach((node, index) => {
      if (!reachable.has(node.id))
        context.addIssue(
          graphIssue(
            `Browser recipe node is unreachable from output: ${node.id}.`,
            ["nodes", index, "id"],
          ),
        );
    });
  });

export function parseBrowserModelRecipe(input: unknown): BrowserModelRecipe {
  return browserModelRecipeSchema.parse(input);
}

/**
 * Replace exactly one already-identified node without mutating the recipe.
 * The replacement must keep the node ID and produce a valid whole graph before
 * the revision is incremented.
 */
export function replaceBrowserModelRecipeNode(
  recipe: BrowserModelRecipe,
  nodeId: string,
  replacement: unknown,
  expectedRevision: number,
): BrowserModelRecipe {
  const current = browserModelRecipeSchema.parse(recipe);
  if (current.revision !== expectedRevision)
    throw new Error(
      `Browser recipe revision is stale: expected ${expectedRevision}, current ${current.revision}.`,
    );
  if (!current.nodes.some((node) => node.id === nodeId))
    throw new Error(`Browser recipe node does not exist: ${nodeId}.`);

  const nextNode = browserModelNodeSchema.parse(replacement);
  if (nextNode.id !== nodeId)
    throw new Error(
      `Browser recipe replacement must preserve node ID ${nodeId}; received ${nextNode.id}.`,
    );

  return browserModelRecipeSchema.parse({
    ...current,
    revision: current.revision + 1,
    nodes: current.nodes.map((node) => (node.id === nodeId ? nextNode : node)),
  });
}

export const browserModelRecipeLimits = Object.freeze({
  maxNodes: MAX_NODES,
  maxDepth: MAX_DEPTH,
  maxSegments: MAX_SEGMENTS,
  maxCoordinateMeters: MAX_COORDINATE_METERS,
  maxDimensionMeters: MAX_DIMENSION_METERS,
  maxRotationRadians: MAX_ROTATION_RADIANS,
  maxScale: MAX_SCALE,
  maxMeshVertices: MAX_BROWSER_MESH_VERTICES,
  maxMeshTriangles: MAX_BROWSER_MESH_TRIANGLES,
  maxMeshRecipeVertices: MAX_BROWSER_MESH_RECIPE_VERTICES,
  maxMeshRecipeTriangles: MAX_BROWSER_MESH_RECIPE_TRIANGLES,
  minTubeRadius: MIN_BROWSER_TUBE_RADIUS,
  maxTubeRadius: MAX_BROWSER_TUBE_RADIUS,
  maxTubePathPoints: MAX_BROWSER_TUBE_PATH_POINTS,
  defaultTubeSegments: DEFAULT_BROWSER_TUBE_SEGMENTS,
  maxTubeSegments: MAX_BROWSER_TUBE_SEGMENTS,
  maxComposeInputs: MAX_COMPOSE_INPUTS,
  maxCopyCount: MAX_COPY_COUNT,
  maxExpandedLeaves: MAX_EXPANDED_LEAVES,
});

